-- The administration of the pricing creates the policies, so the ids must be generated by the database
SET FOREIGN_KEY_CHECKS = 0;
ALTER TABLE commercial_policy MODIFY id bigint NOT NULL AUTO_INCREMENT;
ALTER TABLE commercial_policy_carrier MODIFY id bigint NOT NULL AUTO_INCREMENT;
SET FOREIGN_KEY_CHECKS = 1;

-- Audit of the changes
ALTER TABLE commercial_policy ADD COLUMN created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE commercial_policy ADD COLUMN updated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP;

-- A carrier can appear only once in each policy
ALTER TABLE commercial_policy_carrier ADD CONSTRAINT uk_commercial_policy_carrier UNIQUE (commercial_policy_id, carrier);
